find / \( -path /proc -o -path /sys -o -path /dev \) -prune -o -type f -exec sh -c 'for f do case "$f" in */.bashrc|*/.bash_profile|*/.bash_login|*/.bash_logout|*/.profile|*/.zshrc|*/.zshenv|*/.zprofile|*/.zlogin|*/.zlogout|*/.kshrc|*/.cshrc|*/.tcshrc|*/.login|*/.logout|*/.xsession|*/.xinitrc|*/config.fish|*/fish/conf.d/*|/etc/profile|/etc/bash.bashrc|/etc/bashrc|/etc/profile.d/*|/etc/zsh/*) printf "%s\0" "$f"; continue;; esac; if test -x "$f" || test "$(head -c 2 -- "$f" 2>/dev/null)" = "#!"; then printf "%s\0" "$f"; fi; done' sh {} +
